-- Databricks Free Edition: bronze for 2011, same pattern as 05_phase2_full_load.sql
-- (2015). Part of the 5-year extension (2026-09-29) - each year gets its own bronze
-- table because each year's CSV has a different column set (454 columns for 2011;
-- see scope_and_gaps.md (local notes) for the full 454/359/336/279/330 breakdown). Silver unions
-- all 5 bronze tables together (see 03b_silver_multiyear.sql).

DROP TABLE IF EXISTS workspace.bronze.brfss_2011;

CREATE TABLE workspace.bronze.brfss_2011 AS
